#!/usr/bin/env bash
# Работает ли воркер после выката (спека backend-delivery, «Развёртывание
# проверяет, что воркер работает»).
#
# HTTP у воркера нет, поэтому живость — это состояние контейнера. «Запущен»
# мало: при падении Docker перезапускает его, и в момент проверки он снова
# запущен. Живым считаем контейнер, который 30 секунд подряд запущен и ни разу
# не перезапустился; опрос каждые 5 секунд видит и быстрый рестарт — по
# выросшему счётчику. Окно длиннее жизни процесса ловит любую петлю падений с
# периодом до 30 секунд: после падения процесса, прожившего больше 10 секунд,
# Docker сбрасывает задержку и поднимает его сразу, и короткое окно такую
# петлю пропускало. Рестарты в начале, пока брокер не готов (depends_on его не
# ждёт), окно не засчитывает и начинает заново; на всё — до 90 секунд.
#
# Не устоялся — печатает хвост лога воркера и падает.
#
# `-e` нет намеренно: пустой ответ `state` (контейнера нет, ssh упал) — это
# «ещё не устоялся», очередной опрос, а не конец проверки.
#
# Нужен хост `stand` в ~/.ssh/config (.github/actions/stand-ssh). Параметров нет.
set -uo pipefail

state() {
  ssh stand \
    "docker inspect -f '{{.State.Running}} {{.RestartCount}}' dmc268-worker 2>/dev/null" \
    | grep -E '^(true|false) [0-9]+$' | tail -1
}

hold=30
started="$(date +%s)"
last=""
stable_since="$started"
while [ $(( $(date +%s) - started )) -lt 90 ]; do
  now="$(date +%s)"
  current="$(state)"
  if [ -n "$current" ] && [ "${current%% *}" = "true" ] && [ "$current" = "$last" ]; then
    if [ $(( now - stable_since )) -ge "$hold" ]; then
      echo "воркер работает ${hold} с без рестартов, рестартов всего: ${current##* }"
      exit 0
    fi
  else
    [ -n "$last" ] && echo "воркер ещё не устоялся: было '${last}', стало '${current}'"
    last="$current"
    stable_since="$now"
  fi
  sleep 5
done

echo "::error::воркер не проработал ${hold} с без рестартов за полторы минуты"
ssh stand "docker logs --tail 50 dmc268-worker 2>&1" || true
exit 1
